INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('857d72519c2d5a40be89425a22981f8e', '潘家峪惨案', '', '惨案', '', '', '河北', '', '河北', '0', '1', '伪职：伪丰润县县长，兼警备大队长、新民会会长；参与策划潘家峪惨案，部署全县扫荡，强征粮款民夫资敌。；结局：抗战胜利公审判处死刑', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('1147970d1b1551db8f4cf274422f38da', '玉田大抓捕惨案', '', '惨案', '', '', '河北', '', '河北', '0', '1', '伪职：伪玉田县县长；配合日军铃木启久，推行第四次治安强化运动；组建反共自卫团、棍儿团，炮制八大杀禁律，一周抓捕三千余抗日人员，制造玉田大抓捕惨案唐山党史网。；结局：冀东民主政府公审死刑', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('61349ac053fa5bcab1b80682a847e560', '王厂沟惨案', '', '惨案', '', '', '河北', '承德', '河北 承德', '0', '1', '伪职：伪满讨伐队头目，龙须门讨伐队；参与王厂沟惨案，屠杀平民 49 人、八路军干部战士多人，在承德??青龙??兴隆疯狂讨伐扫荡。；结局：1946??03??13 承德特别法庭公审枪决', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('ad335e78c8835046b598718227395d3f', '白家辛庄惨案', '', '惨案', '', '', '山西', '朔州', '山西 朔州', '0', '1', '伪职：五地委秘书叛变，大特务；罪行：核心叛徒，出卖情报酿成白家辛庄惨案，168 名抗日干部学员遇难，是雁北重大惨案祸首之一。；结局：解放后公审枪决', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('16b7f0fc8f0b56e89674bb9bfd3b16ad', '石洞惨案', '', '惨案', '', '', '安徽', '六安', '安徽 六安', '0', '1', '伪职：霍山便衣汉奸；罪行：带路日军扫荡大河厂，砍断电话线嫁祸乡民，酿成石洞全家 13 口被炸死惨案，烧杀劫掠乡村。；结局：霍山地方武装捕获正法。', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('fcaf68647e5158318b87277bb4408c20', '范家湾惨案', '', '惨案', '', '', '安徽', '铜陵', '安徽 铜陵', '0', '1', '伪职：顺安特务大队长（双料特务）；罪行：伪装进步骗取皖南行署参议员身份，公开叛变投敌；出卖地下党组织，抓捕杀害督导处主任陈益卿；勾结中统，组建特务武装；向日军告密直接酿成范家湾惨案，致使巫希权等 28 位新四军指战员牺牲。；结局：抗战胜利后肃奸捕获，判处死刑处决。', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('294bfa2599055993b20919f7038b273c', '起义警察惨案', '', '惨案', '', '', '内蒙古', '通辽', '内蒙古 通辽', '0', '1', '伪职：伪扎鲁特旗警务科长；假意参加起义，出卖加林台等人，直接制造起义警察惨案，双手沾满鲜血。；结局：1945 年光复后公审枪决', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('f71786b8956f56068a40f4254fef7c14', '门楼下惨案', '', '惨案', '', '', '江苏', '无锡', '江苏 无锡', '0', '1', '伪职：伪乡长兼清乡大队长；罪行：向日军告密新四军驻地情报，直接引发门楼下惨案，致使日军奔袭扫荡，残害百姓无锡市档案...。；结局：抗战胜利后公审处决。', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('18aefee7a7275e0cbcd2db3d090ed25b', '雒贵琦惨案', '', '惨案', '', '', '山西', '吕梁', '山西 吕梁', '0', '1', '伪职：石门墕据点伪维持会总头目；罪行：土豪劣绅投敌；盘踞石门墕据点，抓捕、悬赏缉拿我方干部；引日伪军制造雒贵琦惨案，残害大批抗日军民。；结局：武工队锄奸击毙', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('689bebc26ff853bab9995985cca50488', '（通用描述）制造多起惨案', '', '惨案', '', '', '山东', '济宁', '山东 济宁', '1', '29', '伪职：伪兴隆县县长；强力推行集家并村，强修人圈，疯狂清剿雾灵山抗日根据地，制造多起惨案。；结局：1945 被俘，公审判处死刑', '[]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('d56e0c215d91579c957d7dd650cfc567', '崖山之战', '张世杰灭宋崖山之战', '战役', '宋末', '1279', '广东', '江门', '广东 江门', '0', '0', '南宋祥兴二年，元将张弘范率水师围攻崖山。宋将张世杰力战二十余日，终因寡不敌众，水师全歼。丞相陆秀夫负少帝赵昺投海殉国，随行军民十余万赴死，宋祚断绝——华夏全境首次沦于异族之手。', '["崖山", "张世杰", "陆秀夫", "张弘范"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('8a7a5673727d5a75b27a5d8fb6a27135', '甲申国难', '', '国难', '明末', '1644', '北京', '', '北京', '0', '0', '明崇祯十七年甲申，李自成率大顺军攻陷北京，崇祯帝自缢于煤山，明廷倾覆。旋即辽东总兵吴三桂开关迎敌，引清军入关击败大顺军，神州易主，入关清军随即推行剃发易服之令。', '["甲申", "李自成", "崇祯", "吴三桂"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('e5b611ae9e9c5768954110fcdaed86c7', '扬州十日', '', '大屠杀', '明末', '1645', '江苏', '扬州', '江苏 扬州', '0', '0', '清豫亲王多铎挥师南下克扬州，史可法死节。城破后清军屠城十日，据《扬州十日记》所载，死者逾八十万，尸骨山积，血流成渠。', '["扬州", "史可法"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('54ff2ada0ec152c1998f49a7d753fd1e', '嘉定三屠', '', '大屠杀', '明末', '1645', '上海', '嘉定', '上海 嘉定', '0', '0', '清廷强颁剃发令，嘉定军民三次起兵抗清，朱瑛、侯峒曾、吴之藩等先后举义。清军三次破城屠戮，死难者无算，是为"嘉定三屠"。', '["嘉定"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('67ec001cd90a5142a909f76afc2e03ea', '吴三桂弑永历', '吴三桂杀南明皇帝', '国难', '明末', '1662', '云南', '昆明', '云南 昆明', '0', '0', '明末降将吴三桂率清兵入缅，执南明永历帝朱由榔，绞杀于昆明篦子坡。南明覆亡，明祚尽绝，汉奸之祸延及亡国之君。', '["永历", "吴三桂", "昆明"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('7ee8d0b2e2d954fa8c51a638881d5a5e', '九一八事变', '918事变', '事变', '抗日战争时期', '1931', '辽宁', '沈阳', '辽宁 沈阳', '0', '0', '日军关东军自炸南满铁路柳条湖段，反诬中国军队所为，藉机炮轰沈阳北大营。东北军奉不抵抗之令撤入关内，未及数月，东北三省百万平方公里国土沦陷敌手。', '["九一八", "柳条湖", "沈阳"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('1d475a6135c85af1bd426c5ae5188cef', '七七事变', '', '事变', '抗日战争时期', '1937', '北京', '丰台', '北京 丰台', '0', '0', '日军在卢沟桥附近进行所谓"夜间演习"，借口一名士兵失踪，向中国守军第二十九军发动进攻。中国军队奋起还击，全面抗战由此爆发，中华民族进入八年浴血之岁月。', '["七七", "卢沟桥"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('05bd4988c5d75d278dd41322a624f72b', '淞沪会战', '淞沪抗战', '战役', '抗日战争时期', '1937', '上海', '', '上海', '0', '0', '日军大举进攻上海，中国军队倾精锐之师血战淞沪三月，粉碎其"三月亡华"之妄想。此役中国军人伤亡逾三十万，为抗战初期规模最大、最为惨烈之会战。', '["淞沪", "上海"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('66e792a65eba5b9a804accf5a11ad088', '南京大屠杀', '', '大屠杀', '抗日战争时期', '1937', '江苏', '南京', '江苏 南京', '0', '0', '日军攻陷南京后，进行长达六周有组织之大屠杀、淫掠与焚毁。据战后南京军事法庭与远东国际军事法庭判定，遇难同胞逾三十万，为近代东亚最为骇人听闻之屠城惨案。', '["南京"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('94af8984a8b854e9a54a9e983e8d71eb', '旅顺大屠杀', '', '大屠杀', '', '1894', '辽宁', '大连', '辽宁 大连', '0', '1', '甲午战争期间，日军攻陷旅顺后残酷屠戮城中山民军民逾两万，为中国近代史上惨绝人寰的大屠杀之一。', '["旅顺大屠杀"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('cc812b6ab8bc567d925a6f7586d54607', '插箭岭屠杀', '', '屠杀', '', '', '河北', '邯郸', '河北 邯郸', '0', '1', '日本侵华时期邯郸一带的屠杀干部事件，伪邯郸警察所长卢万寿配合特务抓捕抗日人员直接参与。', '["插箭岭屠杀"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('5da664c9b26d59c8a3e3e555c1e55483', '芜湖城内大屠杀', '', '大屠杀', '', '', '安徽', '芜湖', '安徽 芜湖', '0', '1', '日寇侵占芜湖时，汉奸任凤昌引狼入室，带日军开进芜湖制造城内大屠杀。', '["芜湖城内大屠杀"]', '2026-09-11 08:21:11.231430', '2026-09-11 08:21:11.231430');
